function decodeWithKey(key: string, message: string): string {
  let out = "";
  for (const ch of message) {
    if (ch === " ") { out += " "; continue; }
    const seen = new Set<string>();
    for (const k of key) {
      if (k === " ") continue;
      if (k === ch) break;
      seen.add(k);
    }
    out += String.fromCharCode(97 + seen.size);
  }
  return out;
}

