function decodeWithKey(key: string, message: string): string {
  const table = new Map<string, string>();
  let next = 0;
  for (const k of key) {
    if (k !== " " && !table.has(k)) table.set(k, String.fromCharCode(97 + next++));
  }
  let out = "";
  for (const ch of message) out += ch === " " ? " " : table.get(ch)!;
  return out;
}

